/**
 * Administrator metadata lookup requests behind /catalog-reviews/:id/lookup, creating a review, which queues its one automatic run,
 * and the review save and Luna acceptance that re-rank its run: reading an existing-Album review's allowlisted lookup view with its
 * summary, reading one candidate's rows and each member's options for pairing the members by hand, submitting a name, retrying,
 * choosing a candidate (or none) and answering conflicts. Each change runs inside the review protocol (mutateAdminProject with the review policy, never the import
 * protocol), so it is one review receipt (`lookup`, `lookup-retry`, `lookup-choose` or `lookup-resolve`) and one transaction with
 * the lookup record (and, for a submission or retry, the review's conversion to format 3): a refusal writes nothing, and a lost
 * response replays. A choice or an answer writes only the review's private draft; nothing here writes the catalog.
 */
import { ObjectId } from 'mongodb';
import { metadataLookupConfiguration, type MetadataLookupConfiguration } from '../../config/metadataLookup';
import { adoptCatalogReview, catalogReviewProjectPolicy, createCatalogReview, editCatalogReview } from '../catalog/adminCatalogReviewService';
import type { CatalogReviewResponse } from '../catalog/adminCatalogReviewContract';
import { AdminImportError, objectId } from '../import/adminImportContract';
import { importCollection, importLookupRecord, mutateAdminProject, parseAdminProjectMutation, withImportAdmin } from '../import/adminImportService';
import { parseDraftPath } from '../import/adminImportValueState';
import { isLookupCandidateKey } from './lookupContract';
import { catalogReviewPairingView, type CatalogReviewPairingResponse } from './lookupPairingView';
import { catalogReviewLookupView, type CatalogReviewLookupView } from './lookupView';
import { chooseLookupCandidate, lookupAnswersNeeded, resolveLookupConflicts } from './lookupValueApplication';
import { parseLookupAnswers, parseLookupChoice, parseLookupSubmission, storeLookupRecord } from './metadataLookupRequests';
import { lookupRunActive } from './metadataLookupRecord';
import {
    adminImportLookupCollection, admitMetadataLookup, queueCatalogReviewLookup, queueMetadataLookup, readLookupApplicationContext, rerankCatalogReviewLookup
} from './metadataLookupService';

/**
 * What a review waits for: an active run (`waiting.lookup`, from the run's own state: one that can still send a request, as apply
 * checks) or analysis (queued, running, or a stopped call still settling, as apply checks), the answers lookup needs, and whether
 * this server offers lookup at all.
 */
export type CatalogReviewLookupSummary = { waiting: { lookup: boolean; analysis: boolean }; needsAnswer: { tie: boolean; conflicts: string[] }; lookupAvailable: boolean };
/** `valueRevision` counts lookup applications, which change the draft without a new `revision`, so a reader notices them. */
export type CatalogReviewLookupResponse = { lookup: CatalogReviewLookupView | null; revision: number; valueRevision: number; summary: CatalogReviewLookupSummary };
const notFound = () => new AdminImportError(404, 'ADMIN_CATALOG_REVIEW_NOT_FOUND');

/**
 * The review's lookup view (null before any run, with its timeline), its revision and value revision and its summary, read in
 * one snapshot. Of its server-only capture the review is read without the expected tracklist and member durations; the view's
 * timeline reads only the credited names in it, to admit the Artist names the run searched (catalogReviewSearchTexts), and
 * nothing of the capture is projected into the response. An applied review reads too. A malformed ID or a project that is not a
 * review is not found.
 */
export async function getCatalogReviewLookup(actor: string, id: string, configuration: () => MetadataLookupConfiguration = metadataLookupConfiguration): Promise<CatalogReviewLookupResponse> {
    if (!objectId(id)) throw notFound();
    return withImportAdmin(actor, async session => {
        const doc = await importCollection().findOne({ _id: new ObjectId(id), purpose: 'catalogReview' },
            { session, projection: { 'catalogCapture.album.expectedTracklist': 0, 'catalogCapture.members.duration': 0 } });
        if (!doc) throw notFound();
        const stored = await importLookupRecord(doc._id, session), needed = lookupAnswersNeeded(stored, doc, { append: false });
        const slots = new Set((Array.isArray(doc.manifest?.files) ? doc.manifest.files : []).map(file => file.slotId));
        const available = configuration().available, analysis = doc.analysis;
        return {
            lookup: stored ? catalogReviewLookupView(stored, doc, { timeline: true }) : null, revision: doc.revision,
            valueRevision: Number.isSafeInteger(doc.valueRevision) && doc.valueRevision! >= 0 ? doc.valueRevision! : 0,
            summary: {
                // The run's own state, never the review's gate, which an earlier release's worker may leave blocking; analysis also
                // waits for a stopped call the worker still settles, which apply refuses too.
                waiting: { lookup: lookupRunActive(stored, new Date(), available),
                    analysis: analysis?.state === 'queued' || analysis?.state === 'running' || (Array.isArray(analysis?.chunks) && analysis.chunks.some(chunk => chunk?.state === 'inflight')) },
                needsAnswer: { tie: needed.tie, conflicts: needed.conflicts.filter(path => !path.startsWith('tracks.') || slots.has(path.split('.')[1])) },
                lookupAvailable: available
            }
        };
    });
}

/**
 * GET /catalog-reviews/:id/lookup/candidates/:key/pairing: the hand-pairing read of candidate `key` (lookupPairingView.ts), the review
 * and its lookup record (only that candidate) read in one snapshot as the current administrator; it stores nothing in either (only
 * the administrator fence every review read writes). An applied review reads too. A malformed ID or key, or a project that is not a
 * review, is not found (the route answers a discarded one as discarded); while this server cannot run lookup, a saved pairing could
 * not compare again, so the read is unavailable.
 */
export async function getCatalogReviewLookupPairing(actor: string, id: string, key: string,
    configuration: () => MetadataLookupConfiguration = metadataLookupConfiguration): Promise<CatalogReviewPairingResponse> {
    if (!objectId(id) || !isLookupCandidateKey(key)) throw notFound();
    return withImportAdmin(actor, async session => {
        const doc = await importCollection().findOne({ _id: new ObjectId(id), purpose: 'catalogReview' },
            { session, projection: { 'catalogCapture.album.expectedTracklist': 0 } });
        if (!doc) throw notFound();
        if (!configuration().available) throw new AdminImportError(503, 'ADMIN_IMPORT_LOOKUP_UNAVAILABLE');
        // The key matched isLookupCandidateKey, so it is a plain string here; $elemMatch keeps the first candidate with it, as a choice finds it.
        return catalogReviewPairingView(doc, await importLookupRecord(doc._id, session, { run: 1, state: 1, candidates: { $elemMatch: { key } } }), key);
    });
}

/**
 * POST /catalog-reviews: creates an existing-Album review (createCatalogReview) and, where metadata lookup is available, starts its
 * one automatic run from the Album's saved title and primary Artist names in the creation transaction (queueCatalogReviewLookup,
 * which converts the review to format 3 first). A replayed creation returns its stored response and queues nothing; without lookup
 * the review stays format 2 for manual editing; a refusal of the conversion or a failed write stores no review, run or gate.
 */
export const createCatalogReviewWithLookup = (actor: string, raw: unknown): Promise<CatalogReviewResponse> =>
    createCatalogReview(actor, raw, { beforeInsert: async (doc, session) => { await queueCatalogReviewLookup(doc, actor, session); } });

/**
 * `{operationId, expectedRevision, kind, text, artist?}`: looks up a submitted Album or song name with the review's primary Artist
 * names, or with the submitted Artist name in their place, replacing the previous run. A malformed body rejects like every other
 * refusal.
 */
export async function submitCatalogReviewLookup(actor: string, id: string, raw: unknown): Promise<CatalogReviewResponse> {
    const { body, submitted } = parseLookupSubmission(raw);
    return mutateAdminProject(actor, id, body, 'lookup', async (doc, session) => {
        await queueMetadataLookup(doc, { kind: 'submit', actorId: actor, operationId: body.operationId, submitted }, session);
    }, catalogReviewProjectPolicy);
}

/** `{operationId, expectedRevision}`: repeats the last run's input and queries as a new run. */
export async function retryCatalogReviewLookup(actor: string, id: string, raw: unknown): Promise<CatalogReviewResponse> {
    const body = parseAdminProjectMutation(raw, []);
    return mutateAdminProject(actor, id, body, 'lookup-retry', async (doc, session) => {
        await queueMetadataLookup(doc, { kind: 'retry', actorId: actor, operationId: body.operationId }, session);
    }, catalogReviewProjectPolicy);
}

/**
 * `{operationId, expectedRevision, run, candidateKey}`: applies a candidate of the current run, or none (`candidateKey: null`), to
 * the review's draft. Admitted only for a format-3 review whose capture is readable and whose source is current
 * (admitMetadataLookup's check: 409 ADMIN_IMPORT_LOOKUP_REFUSED, ADMIN_IMPORT_RELOAD_REQUIRED or
 * ADMIN_CATALOG_REVIEW_SOURCE_CHANGED); the run and candidate refusals are the import's (chooseLookupCandidate). A ranking whose
 * evidence changed, as one stored before position hints existed whose members carry them has, re-ranks first in the same
 * transaction (rerankCatalogReviewLookup; a preselection it applies is then replaced by the choice), so the view after the choice
 * rests on the current pairing, while the choice follows the pairing the ranking read before it showed.
 */
export async function chooseCatalogReviewLookup(actor: string, id: string, raw: unknown): Promise<CatalogReviewResponse> {
    const { body, run, candidateKey } = parseLookupChoice(raw);
    return mutateAdminProject(actor, id, body, 'lookup-choose', async (doc, session) => {
        await admitMetadataLookup(doc, session, 'check');
        const shown = await adminImportLookupCollection().findOne({ _id: doc._id }, { session });
        await rerankCatalogReviewLookup(doc, actor, session);
        const stored = await adminImportLookupCollection().findOne({ _id: doc._id }, { session });
        await storeLookupRecord(chooseLookupCandidate(doc, stored, { run, candidateKey, actorId: actor, operationId: body.operationId, shown }, new Date(),
            await readLookupApplicationContext(doc, stored, session)), session);
    }, catalogReviewProjectPolicy);
}

/**
 * `{operationId, expectedRevision, run, candidateKey, answers}`: answers 1 to 406 conflicts of the applied candidate, all or
 * nothing, on the review's lookup value paths (its expected tracklist and member Artist entries included) of this manifest. Admitted
 * as a choice is; the answer refusals are the import's (resolveLookupConflicts).
 */
export async function resolveCatalogReviewLookup(actor: string, id: string, raw: unknown): Promise<CatalogReviewResponse> {
    const { body, run, candidateKey, answers } = parseLookupAnswers(raw, { review: true });
    return mutateAdminProject(actor, id, body, 'lookup-resolve', async (doc, session) => {
        await admitMetadataLookup(doc, session, 'check');
        const parsed = answers.map(answer => ({ ...answer, path: parseDraftPath(answer.path, doc.manifest, { reviewPaths: true }) }));
        const stored = await adminImportLookupCollection().findOne({ _id: doc._id }, { session });
        await storeLookupRecord(resolveLookupConflicts(doc, stored, { run, candidateKey, answers: parsed }, new Date()), session);
    }, catalogReviewProjectPolicy);
}

/**
 * PATCH /catalog-reviews/:id: the review save (editCatalogReview) whose per-path changes then re-rank a format-3 review's completed
 * run in the same transaction when a member's own Disc or Track Number changed (rerankCatalogReviewLookup), applying a sole
 * preselection while the run has applied nothing.
 */
export const saveCatalogReview = (actor: string, id: string, raw: unknown): Promise<CatalogReviewResponse> =>
    editCatalogReview(actor, id, raw, { afterChanges: (doc, session) => rerankCatalogReviewLookup(doc, actor, session) });

/**
 * POST /catalog-reviews/:id/adopt: accepting and rejecting Luna suggestions (adoptCatalogReview), which re-ranks the review's
 * completed run in the same transaction as a save does when an accepted Disc or Track Number changed a member's own numbers.
 */
export const adoptCatalogReviewSuggestions = (actor: string, id: string, raw: unknown): Promise<CatalogReviewResponse> =>
    adoptCatalogReview(actor, id, raw, { afterChanges: (doc, session) => rerankCatalogReviewLookup(doc, actor, session) });
